INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bdf97817-250e-4e91-b8a6-0817621003d6', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 6, 'A paciência com o processo', NULL, '{"intro": "A impaciência é a voz da pressa, e a cura exige tempo.", "prayer": "Respire profundamente 5 vezes, aceitando o seu tempo.", "practice": "Observe o seu ritmo hoje, sem querer forçar nada.", "reflection": "A cura é uma espiral, não uma linha reta.", "journal_prompt": "Por que você tem tanta pressa em ser perfeito?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('71feb284-a2c1-4cb8-a060-d7aba375b100', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 7, 'O início da vida', NULL, '{"intro": "Agora que a ferida não te define, a vida pode florescer.", "prayer": "Agradeça pela sua própria existência.", "practice": "Planeje um pequeno gesto de cuidado com você mesmo.", "reflection": "Curar é, finalmente, começar a viver.", "journal_prompt": "Qual é o primeiro passo da sua vida renovada?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;